import { gsap } from 'gsap';
import { ScrollTrigger } from 'gsap/ScrollTrigger';

gsap.registerPlugin(ScrollTrigger);

// Initialize animations for the entire page
export const initAnimations = () => {
  // Hero section animations (only on page load)
  gsap.from('.hero__tag', {
    y: 30,
    opacity: 0,
    duration: 0.8,
    delay: 0.2,
    ease: 'power3.out'
  });

  gsap.from('.hero__title', {
    y: 50,
    opacity: 0,
    duration: 1,
    delay: 0.4,
    ease: 'power3.out'
  });

  gsap.from('.hero__subtitle', {
    y: 30,
    opacity: 0,
    duration: 1,
    delay: 0.6,
    ease: 'power3.out'
  });

  gsap.from('.hero__cta', {
    y: 30,
    opacity: 0,
    duration: 1,
    delay: 0.8,
    ease: 'power3.out'
  });

  gsap.from('.hero__visual', {
    y: 40,
    opacity: 0,
    duration: 1,
    delay: 1,
    ease: 'power3.out'
  });

  // Simple scroll animations for all sections
  gsap.utils.toArray('.text-animate').forEach(element => {
    gsap.from(element, {
      y: 30,
      opacity: 0,
      duration: 0.8,
      ease: 'power3.out',
      scrollTrigger: {
        trigger: element,
        start: 'top 85%',
        toggleActions: 'play none none reverse'
      }
    });
  });

  gsap.utils.toArray('.card-animate').forEach(element => {
    gsap.from(element, {
      y: 50,
      opacity: 0,
      duration: 0.8,
      ease: 'power3.out',
      scrollTrigger: {
        trigger: element,
        start: 'top 80%',
        toggleActions: 'play none none reverse'
      }
    });
  });
};

// Stagger animation for lists
export const staggerAnimation = (selector, options = {}) => {
  const elements = gsap.utils.toArray(selector);
  gsap.from(elements, {
    y: 30,
    opacity: 0,
    duration: 0.6,
    stagger: 0.1,
    ease: 'power2.out',
    scrollTrigger: {
      trigger: selector,
      start: 'top 85%',
      end: 'bottom 15%',
      toggleActions: 'play none none reverse',
      ...options.scrollTrigger
    },
    ...options
  });
};

// Parallax effect
export const parallaxEffect = (selector, speed = 0.5) => {
  const elements = gsap.utils.toArray(selector);
  elements.forEach((element) => {
    gsap.to(element, {
      yPercent: -50 * speed,
      ease: 'none',
      scrollTrigger: {
        trigger: element,
        start: 'top bottom',
        end: 'bottom top',
        scrub: true
      }
    });
  });
};

// Refresh ScrollTrigger
export const refreshScrollTrigger = () => {
  setTimeout(() => {
    ScrollTrigger.refresh();
  }, 100);
};

// Kill all ScrollTrigger instances
export const killScrollTrigger = () => {
  ScrollTrigger.killAll();
};
